mapper.select:
SELECT * FROM history
WHERE conversation_id = #{conversationId}
ORDER BY id ASC

SELECT * FROM (
    SELECT * FROM history
    WHERE conversation_id = #{conversationId}
    ORDER BY id DESC
    LIMIT #{limit}
) t ORDER BY t.id ASC

SELECT * FROM (
    SELECT h.* FROM history h
    INNER JOIN conversation c ON c.id = h.conversation_id
    WHERE c.user_id = #{userId} AND h.sender = 'user'
    ORDER BY h.id DESC LIMIT #{limit}
) t ORDER BY t.id ASC
